import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../estado/publicaciones_provider.dart';
import 'login_screen.dart';

class PublicacionesScreen extends ConsumerStatefulWidget {
  const PublicacionesScreen({super.key});

    @override
      ConsumerState<PublicacionesScreen> createState() =>
            _PublicacionesScreenState();
            }

            class _PublicacionesScreenState extends ConsumerState<PublicacionesScreen> {
              final _scroll = ScrollController();

                @override
                  void initState() {
                      super.initState();
                          _scroll.addListener(_alDesplazar);
                            }

                              // Detecta que el usuario se acerca al final de la lista
                                void _alDesplazar() {
                                    if (_scroll.position.pixels >= _scroll.position.maxScrollExtent - 200) {
                                          ref.read(publicacionesProvider.notifier).cargarMas();
                                              }
                                                }

                                                  @override
                                                    void dispose() {
                                                        _scroll.dispose();
                                                            super.dispose();
                                                              }

                                                                // Cierra sesión y borra el historial para no poder volver con "atrás"
                                                                  void _cerrarSesion() {
                                                                      Navigator.pushAndRemoveUntil(
                                                                            context,
                                                                                  MaterialPageRoute(builder: (_) => const LoginScreen()),
                                                                                        (ruta) => false,
                                                                                            );
                                                                                              }

                                                                                                @override
                                                                                                  Widget build(BuildContext context) {
                                                                                                      final estado = ref.watch(publicacionesProvider);
                                                                                                          final notifier = ref.read(publicacionesProvider.notifier);

                                                                                                              return Scaffold(
                                                                                                                    appBar: AppBar(
                                                                                                                            title: const Text('Publicaciones'),
                                                                                                                                    actions: [
                                                                                                                                              IconButton(
                                                                                                                                                          onPressed: _cerrarSesion,
                                                                                                                                                                      icon: const Icon(Icons.logout),
                                                                                                                                                                                  tooltip: 'Cerrar sesión',
                                                                                                                                                                                            ),
                                                                                                                                                                                                    ],
                                                                                                                                                                                                          ),
                                                                                                                                                                                                                body: _contenido(estado, notifier),
                                                                                                                                                                                                                    );
                                                                                                                                                                                                                      }

                                                                                                                                                                                                                        Widget _contenido(EstadoListado estado, PublicacionesNotifier notifier) {
                                                                                                                                                                                                                            // Estado: cargando
                                                                                                                                                                                                                                if (estado.cargando) {
                                                                                                                                                                                                                                      return const Center(child: CircularProgressIndicator());
                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                              // Estado: error con opción de reintentar
                                                                                                                                                                                                                                                  if (estado.error != null) {
                                                                                                                                                                                                                                                        return Center(
                                                                                                                                                                                                                                                                child: Padding(
                                                                                                                                                                                                                                                                          padding: const EdgeInsets.all(24),
                                                                                                                                                                                                                                                                                    child: Column(
                                                                                                                                                                                                                                                                                                mainAxisSize: MainAxisSize.min,
                                                                                                                                                                                                                                                                                                            children: [
                                                                                                                                                                                                                                                                                                                          const Icon(Icons.wifi_off, size: 48),
                                                                                                                                                                                                                                                                                                                                        const SizedBox(height: 12),
                                                                                                                                                                                                                                                                                                                                                      Text(estado.error!, textAlign: TextAlign.center),
                                                                                                                                                                                                                                                                                                                                                                    const SizedBox(height: 16),
                                                                                                                                                                                                                                                                                                                                                                                  ElevatedButton(
                                                                                                                                                                                                                                                                                                                                                                                                  onPressed: notifier.cargarInicial,
                                                                                                                                                                                                                                                                                                                                                                                                                  child: const Text('Reintentar'),
                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                            ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Estado: lista vacía
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (estado.items.isEmpty) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return RefreshIndicator(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onRefresh: notifier.recargar,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      child: ListView(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                physics: const AlwaysScrollableScrollPhysics(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          children: const [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      SizedBox(height: 120),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Center(child: Text('No hay publicaciones por mostrar.')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Estado: datos
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return RefreshIndicator(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onRefresh: notifier.recargar,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  child: ListView.builder(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          controller: _scroll,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  physics: const AlwaysScrollableScrollPhysics(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          itemCount: estado.items.length + 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  itemBuilder: (context, index) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (index < estado.items.length) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        final p = estado.items[index];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return ListTile(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  leading: CircleAvatar(child: Text('${p.id}')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                title: Text(p.titulo, maxLines: 1, overflow: TextOverflow.ellipsis),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              subtitle: Text(p.cuerpo, maxLines: 2, overflow: TextOverflow.ellipsis),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return _pie(estado, notifier);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Lo que ve el usuario al final de la lista
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Widget _pie(EstadoListado estado, PublicacionesNotifier notifier) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (estado.cargandoMas) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return const Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: EdgeInsets.all(16),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                child: Center(child: CircularProgressIndicator()),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (estado.errorMas != null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            padding: const EdgeInsets.all(16),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    child: Column(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Text(estado.errorMas!, textAlign: TextAlign.center),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      TextButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onPressed: notifier.cargarMas,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  child: const Text('Reintentar'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!estado.hayMas) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return const Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            padding: EdgeInsets.all(16),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    child: Center(child: Text('No hay más publicaciones.')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return const SizedBox.shrink();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }